<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage1; use Obs\ObsClient; use Obs\ObsException; class huawei_obs extends cloudStorage1 { var $obsClient; var $access_key_id; var $access_key_secret; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_obs_custom_upload_dir; $this->protocol = $this->options->cloud_storage_obs_protocol; $this->host = $this->options->cloud_storage_obs_host; $this->folder = $this->options->cloud_storage_obs_folder; $this->endpoint = trim($this->options->cloud_storage_obs_endpoint); $this->access_key_id = trim($this->options->cloud_storage_obs_access_key_id); $this->access_key_secret = trim($this->options->cloud_storage_obs_access_key_secret); $this->bucket = trim($this->options->cloud_storage_obs_bucket); $this->cloud_thumbnail = $this->options->cloud_storage_joinmode_enabled ? 0 : filter_var($this->options->cloud_storage_obs_cloud_thumbnail_enabled, FILTER_VALIDATE_BOOLEAN); $this->cloud_thumbnail_enabled = $this->options->cloud_storage_obs_cloud_thumbnail_enabled; $this->cloud_thumbnail_structure = $this->options->cloud_storage_obs_cloud_thumbnail_structure; $this->silent_scanning = $this->options->cloud_storage_obs_silent_scanning; $this->auto_replace = $this->options->cloud_storage_obs_auto_replace; $this->sync_delete = $this->options->cloud_storage_obs_sync_delete; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_obs_delete_attachment_after_synced; $this->sync_the_website_resource = $this->options->cloud_storage_obs_sync_the_website_resource; $this->website_resource_filetypes = $this->options->cloud_storage_obs_website_resource_filetypes; $this->custom_replacement = $this->options->cloud_storage_obs_custom_replacement; } public function includes() { if ( !class_exists('Obs\ObsClient') ) require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'huaweicloud' . DIRECTORY_SEPARATOR . 'autoload.php'; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { $this->includes(); if ($this->access_key_id && $this->access_key_secret && $this->endpoint) { $this->obsClient = new ObsClient([ 'key' => $this->access_key_id, 'secret' => $this->access_key_secret, 'endpoint' => $this->endpoint, 'exception_response_mode' => false ]); if (isset($_COOKIE['CLOUD_STORAGE_ACCESSED']) && $_COOKIE['CLOUD_STORAGE_ACCESSED']) { $this->accessed = true; return; } try { $resp = $this->obsClient->headBucket([ 'Bucket' => $this->bucket ]); $data = $resp->toArray(); if ($data['HttpStatusCode'] == 200) { $this->accessed = $resp && isset($resp['RequestId']); if ($this->accessed) setcookie('CLOUD_STORAGE_ACCESSED', 1, array( 'expires' => time() + 3600, 'path' => '/', 'domain' => '', 'secure' => true, 'httponly' => true, 'samesite' => 'None' )); } else { print '<div class="error"><p>'.$data['Reason'].'</p></div>'; } } catch (\Obs\Common\ObsException $obsException) { if ($obsException->getStatusCode() === 404){ print '<div class="error"><p>Bucket does not exist</p></div>'; } else { print '<div class="error"><p>'.sprintf("ExceptionCode:%s\n", $obsException->getExceptionCode()).'</p></div>'; print '<div class="error"><p>'.sprintf("getExceptionMessage:%s\n", $obsException->getExceptionMessage()).'</p></div>'; } } } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); try { $resp = $this->obsClient->getObject(array ( 'Bucket' => $this->bucket, 'Key' => $destination_path )); $data = $resp->toArray(); $exist = $data['HttpStatusCode'] != 404; } catch ( ObsException $e ) { do_action( 'qqworld-collector-log', $this->log_id, 'Huawei OBS:', $e->getMessage() ); $exist = false; } return $exist; } public function upload($destination_path, $source_path) { $this->access_service(); if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); $destination_path = preg_replace('/^\//', '', $destination_path); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } try { $resp = $this->obsClient->putObject(array ( 'Bucket' => $this->bucket, 'Key' => $destination_path, 'SourceFile' => $source_path )); $success = $resp && isset($resp['RequestId']); } catch ( ObsException $e ) { do_action( 'qqworld-collector-log', $this->log_id, 'Huawei OSS:', $e->getMessage() ); $success = false; } return $success; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); try { $resp = $this->obsClient->deleteObject(array ( 'Bucket' => $this->bucket, 'Key' => $object, 'VersionId' => '' )); $success = $resp && isset($resp['RequestId']); } catch ( ObsException $e ) { do_action( 'qqworld-collector-log', $this->log_id, 'Huawei OBS:', $e->getMessage() ); $success = false; } return $success; } public function add_could_storage_form($guid) { if (file_exists(WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'huaweicloud' . DIRECTORY_SEPARATOR . 'autoload.php')) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } else { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'-no-sdk.php'; } } public function external_sdk($sdks) { $sdks['cloud-storage']['items']['huawei-obs'] = array( 'label' => __('Huawei Object Storage Service (OBS)', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'huaweicloud' . DIRECTORY_SEPARATOR . 'autoload.php', 'download' => 'huaweicloud.zip', 'extract' => true, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and unzip it to directory <strong>%s</strong>.', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91%E5%B7%A5%E5%85%B7%E5%8C%85%EF%BC%88SDK%EF%BC%89', 'huaweicloud.zip', WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR ) ); return $sdks; } } ?>